#!/bin/bash
# weewx-site-ramdisk.sh
# Installs a static HTML "loading" page onto the WeeWX website tmpfs so
# visitors see something reasonable between a reboot and the next WeeWX
# report-generation cycle (typically ~5 minutes after weewx starts).
#
# How it works:
#   - The master copy lives on the SD card at:
#       /usr/local/share/weewx-ramdisk/loading.html
#     Edit that file if you ever want to change the page.
#   - A systemd oneshot unit copies it onto the tmpfs at
#     /var/www/html/weewx/index.html on every boot, AFTER the tmpfs is
#     mounted but BEFORE nginx and weewx start.
#   - ConditionPathExists=!/var/www/html/weewx/index.html means the service
#     is a no-op if something (usually weewx) has already placed a real
#     index.html there. So once weewx catches up and regenerates reports,
#     the loading page is naturally overwritten — and on the next reboot,
#     the loading page is back until weewx catches up again.
#
# This script also ensures the tmpfs mount for /var/www/html/weewx is
# present in /etc/fstab and mounted. Weewx reports regenerate every few
# minutes, so keeping them on a tmpfs spares the SD card a lot of writes.
#
# Run as root.
set -euo pipefail

if [[ $EUID -ne 0 ]]; then
  echo "Please run as root (sudo)." >&2
  exit 1
fi

SHARE_DIR="/usr/local/share/weewx-ramdisk"
LOADING_SRC="${SHARE_DIR}/loading.html"
WEEWX_WEB_DIR="/var/www/html/weewx"
UNIT="/etc/systemd/system/weewx-loading-page.service"
TMPFS_SIZE="128M"
WEB_OWNER="weewx"
WEB_GROUP="weewx"

mkdir -p "$SHARE_DIR"
mkdir -p "$WEEWX_WEB_DIR"

# --- 0. Ensure /etc/fstab has the tmpfs line and mount it ----------------
# Idempotent: only append if no matching line already exists.
FSTAB_LINE="tmpfs  ${WEEWX_WEB_DIR}  tmpfs  noatime,nosuid,size=${TMPFS_SIZE},uid=${WEB_OWNER},gid=${WEB_GROUP},mode=0755  0  0"
if ! grep -qE "^\s*tmpfs\s+${WEEWX_WEB_DIR}\s+tmpfs\b" /etc/fstab; then
  # Back up fstab the first time we touch it.
  cp -n /etc/fstab "/etc/fstab.bak.$(date +%Y%m%d-%H%M%S)" || true
  echo "$FSTAB_LINE" >> /etc/fstab
  echo "Added tmpfs entry for ${WEEWX_WEB_DIR} to /etc/fstab."
else
  echo "/etc/fstab already has an entry for ${WEEWX_WEB_DIR}; leaving it alone."
fi

# systemd picks up fstab changes via its generator; reload so the
# auto-generated var-www-html-weewx.mount unit is in sync.
systemctl daemon-reload

# Mount it now if it isn't already.
if ! mountpoint -q "$WEEWX_WEB_DIR"; then
  mount "$WEEWX_WEB_DIR"
  echo "Mounted tmpfs at $WEEWX_WEB_DIR."
else
  echo "$WEEWX_WEB_DIR is already a mountpoint."
fi

# --- 1. Write the loading page -------------------------------------------
# Master copy lives here; edit in place to change the page.
cat > "$LOADING_SRC" <<'LOADING_PAGE_EOF'
<!DOCTYPE html>
<html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta http-equiv="refresh" content="60">
    <title>Station Loading...</title>
    <style type="text/css">
        a { color:#5D5D9E; }
        a:visited { color:#5D5D9E; }
        a:active { color:#5C615E; }
        a:hover { color:#B2B3B4; }
        a.wsp48fac406{ color:#0080FF; text-decoration: none}
        a.wsp48fac406:visited{ color:#0080FF; text-decoration: none}
        a.wsp48fac406:active{ color:#8018CB; text-decoration: underline}
        a.wsp48fac406:hover{ color:#0000A0; text-decoration: underline}
        a.wsp63851a2{ color:#FFFFFF; text-decoration: none}
        a.wsp63851a2:visited{ color:#FFFFFF; text-decoration: none}
        a.wsp63851a2:active{ color:#FFFFFF; text-decoration: underline}
        a.wsp63851a2:hover{ color:#C0C0C0; text-decoration: underline}
    </style>
  </head>
  <body style="background-color:#FFFFFF; padding:0;  margin: 0;">
    <div style="text-align:left;">
      <div style="vertical-align: top; position:relative; display: inline-block; width:100%; min-height:11px; background-color:#353535; " id="container_42f466dc">
        <div style="margin: 10px; display: block; " id="container_42f466dc_padding" >
          <div style="text-align:center;">
            <span style="font-size:13pt; font-family:'Lucida Sans Unicode', 'Lucida Grande', sans-serif; color:#FFFFFF; "><a href="" class="wsp63851a2">Please Wait...</a></span>
            <span style="font-size:13pt; font-family:'Lucida Sans Unicode', 'Lucida Grande', sans-serif; color:#FFFFFF; "> </span>
          </div>
        </div>
      </div>
    </div>
    <div style="text-align:center;">
      <div style="vertical-align: top; position:relative; display: inline-block; width:100%; min-height:150px; max-width:700px; background:none; " id="container_78bff89b">
        <div style="margin: 30px; display: block; " id="container_78bff89b_padding" >
          <div style="text-align:center;">
<img src="data:image/png;base64," style="vertical-align: bottom; position:relative; display: inline-block; width:55%; background:none; " id="vantage-view" alt="" title="" />
            <span style="font-size:12pt; font-family:Arial, Helvetica, sans-serif; color:#000000; line-height: 1.5; "><br/><br/></span>
            <span style="font-size:22pt; font-family:'Lucida Sans Unicode', 'Lucida Grande', sans-serif; color:#303030; line-height: 1.5; ">Station Loading...</span>
            <span style="font-size:12pt; font-family:'Lucida Sans Unicode', 'Lucida Grande', sans-serif; color:#000000; line-height: 1.5; "><br/><br/>The station is loading due to a reboot or restart.  This typically takes less than 15 minutes to complete<br/><br/>The page will refresh every 60 seconds until the site is loaded.<br/><br/></span>
            <span style="font-size:12pt; font-family:'Lucida Sans Unicode', 'Lucida Grande', sans-serif; color:#000000; line-height: 1.5; "><a href="https://www.wunderground.com/personal-weather-station/dashboard?ID=KVTVERMO34" target="_blank" class="wsp48fac406">Go to station on Weather Underground →</a></span>
            <span style="font-size:12pt; font-family:'Lucida Sans Unicode', 'Lucida Grande', sans-serif; color:#303030; line-height: 1.5; "><br/><br/></span>
          </div>
          <div style="clear:both"></div>
        </div>
      </div>
    </div>
    <div style="text-align:left;">
      <div style="vertical-align: top; position:relative; display: inline-block; width:100%; min-height:26px; background-color:#353535; " id="container_365f079f">
        <div style="margin: 10px; display: block; " id="container_365f079f_padding" >
          <div style="text-align:center;">
            <span style="font-size:10pt; font-family:'Lucida Sans Unicode', 'Lucida Grande', sans-serif; color:#FFFFFF; ">© 2026 Dan Begallie.  All rights reserved.</span>
          </div>
        </div>
      </div>
    </div>
  </body>
</html>
LOADING_PAGE_EOF

chmod 0644 "$LOADING_SRC"

# --- 2. Install the oneshot systemd unit ---------------------------------
# After= the auto-generated mount unit so the tmpfs is definitely mounted.
# Before= nginx and weewx so the page is in place before they start.
# ConditionPathExists=! so we don't clobber a real weewx-generated index.
cat > "$UNIT" <<'UNIT_EOF'
[Unit]
Description=Install WeeWX loading page onto tmpfs
DefaultDependencies=no
After=var-www-html-weewx.mount local-fs.target
Requires=var-www-html-weewx.mount
Before=nginx.service weewx.service
ConditionPathExists=!/var/www/html/weewx/index.html

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/bin/cp /usr/local/share/weewx-ramdisk/loading.html /var/www/html/weewx/index.html
ExecStart=/bin/chown weewx:weewx /var/www/html/weewx/index.html
ExecStart=/bin/chmod 0644 /var/www/html/weewx/index.html

[Install]
WantedBy=multi-user.target
UNIT_EOF

systemctl daemon-reload
systemctl enable weewx-loading-page.service

# --- 3. If the tmpfs is already mounted and empty, drop it in right now --
if mountpoint -q "$WEEWX_WEB_DIR"; then
  if [[ ! -f "${WEEWX_WEB_DIR}/index.html" ]]; then
    cp "$LOADING_SRC" "${WEEWX_WEB_DIR}/index.html"
    chown weewx:weewx "${WEEWX_WEB_DIR}/index.html" 2>/dev/null || true
    chmod 0644 "${WEEWX_WEB_DIR}/index.html"
    echo "Placed loading page at ${WEEWX_WEB_DIR}/index.html (tmpfs was empty)."
  else
    echo "Leaving existing ${WEEWX_WEB_DIR}/index.html alone."
  fi
else
  echo "NOTE: ${WEEWX_WEB_DIR} is not currently a tmpfs mount."
  echo "      Make sure your /etc/fstab line for it is in place, then reboot."
fi

cat <<'DONE_EOF'

Loading page installer complete.

Verify:
  systemctl cat weewx-loading-page.service
  systemctl status weewx-loading-page.service
  ls -l /var/www/html/weewx/index.html

To edit the loading page later:
  sudo nano /usr/local/share/weewx-ramdisk/loading.html
  # then reboot, or:
  sudo rm /var/www/html/weewx/index.html
  sudo systemctl start weewx-loading-page.service

DONE_EOF